import threading
import time
from datetime import datetime

import customtkinter as ctk
import cv2 as cv
import pandas as pd
from PIL import Image
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import accuracy_score, f1_score, ConfusionMatrixDisplay
from sklearn.model_selection import train_test_split
from matplotlib.figure import Figure
from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg

from calculate_parameters import calculate_parameters

DEFAULT_STREAM_URL = "rtsp://192.168.4.1/mjpeg/1"
DEFAULT_DATA_PATH = "calculated_data.csv"
RANDOM_STATE = 42
CROP_LEFT = 160     # crop turntable edges (same as live_demo.py)
CROP_RIGHT = 200
GUI_REFRESH_MS = 30

def current_time():
    return datetime.now().strftime("%H:%M:%S")


def draw_bounding_box(photo, label):
    """Same logic as live_demo.py: threshold the S channel and box the object."""
    PADDING = 20
    photo_hsv = cv.cvtColor(photo, cv.COLOR_BGR2HSV)
    photo_hsv_blur = cv.GaussianBlur(photo_hsv, (15, 15), 0)
    _, s, _ = cv.split(photo_hsv_blur)
    _, s_thresh = cv.threshold(s, 110, 255, cv.THRESH_BINARY)

    x, y, w, h = cv.boundingRect(s_thresh)
    if w == 0 or h == 0:          # nothing detected
        return photo

    y0 = max(0, y - PADDING)
    y1 = min(photo.shape[0], y + h + PADDING)
    x0 = max(0, x - PADDING)
    x1 = min(photo.shape[1], x + w + PADDING)

    cv.rectangle(photo, (x0, y0), (x1, y1), (0, 255, 0), 2)
    cv.putText(photo, str(label), (x0, max(20, y0 - 10)),
               cv.FONT_HERSHEY_SIMPLEX, 0.9, (0, 255, 0), 2)
    return photo


class ConfusionMatrixWindow(ctk.CTkToplevel):
    """Separate window: one Train button, the confusion matrix, accuracy and F1 score.
    The data path is read from the main window's CSV field when Train is pressed."""

    def __init__(self, app):
        super().__init__(app)
        self.app = app
        self.title("Confusion matrix")
        self.geometry("850x700")
        self.minsize(600, 500)

        self.grid_columnconfigure(0, weight=1)
        self.grid_rowconfigure(1, weight=1)

        # Top bar: train button + status
        top = ctk.CTkFrame(self, fg_color="transparent")
        top.grid(row=0, column=0, sticky="ew", padx=15, pady=(15, 5))
        top.grid_columnconfigure(1, weight=1)

        self.train_btn = ctk.CTkButton(top, text="Train & evaluate", width=180,
                                       command=self.start_evaluation)
        self.train_btn.grid(row=0, column=0, sticky="w")

        self.status = ctk.CTkLabel(top, text="Press train to evaluate the model on a 80/20 split.",
                                   text_color="gray60", anchor="w")
        self.status.grid(row=0, column=1, sticky="ew", padx=15)

        self.progress = ctk.CTkProgressBar(top, mode="indeterminate")
        self.progress.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(8, 0))
        self.progress.set(0)

        # Matrix box
        self.plot_box = ctk.CTkFrame(self, corner_radius=12, border_width=2)
        self.plot_box.grid(row=1, column=0, sticky="nsew", padx=15, pady=5)
        self.plot_box.grid_columnconfigure(0, weight=1)
        self.plot_box.grid_rowconfigure(0, weight=1)

        self.placeholder = ctk.CTkLabel(self.plot_box, text="No confusion matrix yet",
                                        text_color="gray60", font=ctk.CTkFont(size=16))
        self.placeholder.grid(row=0, column=0, sticky="nsew")
        self.canvas = None

        # Score tiles
        scores = ctk.CTkFrame(self, fg_color="transparent")
        scores.grid(row=2, column=0, sticky="ew", padx=15, pady=(5, 15))
        scores.grid_columnconfigure((0, 1), weight=1)
        self.acc_value = self._score_tile(scores, 0, "Accuracy")
        self.f1_value = self._score_tile(scores, 1, "F1 score (weighted)")

        # CTkToplevel sometimes opens behind the main window on Windows
        self.after(150, self._bring_to_front)

    def _score_tile(self, parent, col, title):
        tile = ctk.CTkFrame(parent)
        tile.grid(row=0, column=col, sticky="ew", padx=(0 if col == 0 else 8, 0))
        ctk.CTkLabel(tile, text=title, text_color="gray60").pack(pady=(10, 0))
        value = ctk.CTkLabel(tile, text="-", font=ctk.CTkFont(size=28, weight="bold"))
        value.pack(pady=(0, 10))
        return value

    def _bring_to_front(self):
        self.lift()
        self.focus_force()

    def start_evaluation(self):
        data_path = self.app.data_entry.get().strip()     # path from the main window
        self.train_btn.configure(state="disabled", text="Training…")
        self.status.configure(text=f"Training on {data_path}…", text_color="gray70")
        self.progress.start()
        threading.Thread(target=self._evaluation_worker, args=(data_path,), daemon=True).start()

    def _evaluation_worker(self, data_path):
        # Training runs in a thread; drawing must happen on the GUI thread (self.after)
        try:
            result = self.app.create_confusion_matrix(data_path)
            self.after(0, lambda: self._show_result(*result))
        except Exception as e:
            self.app.log(f"Confusion matrix failed: {e}")
            self.after(0, lambda: self.status.configure(text=f"Failed: {e}", text_color="#ef5350"))
        finally:
            self.after(0, self._evaluation_done)

    def _evaluation_done(self):
        self.progress.stop()
        self.progress.set(0)
        self.train_btn.configure(state="normal", text="Train & evaluate")

    def _show_result(self, classes, y_test, y_predicted, accuracy, f1):
        dark = ctk.get_appearance_mode() == "Dark"
        bg = "#2b2b2b" if dark else "#dbdbdb"     # matches CTkFrame default colours
        fg = "white" if dark else "black"

        fig = Figure(figsize=(6, 5), dpi=100, facecolor=bg)
        ax = fig.add_subplot(111)
        ConfusionMatrixDisplay.from_predictions(y_test, y_predicted, labels=classes,
                                                cmap="Blues", ax=ax, colorbar=True,
                                                xticks_rotation=45)
        ax.set_title("Confusion matrix (test set)", color=fg)
        ax.set_facecolor(bg)
        ax.xaxis.label.set_color(fg)
        ax.yaxis.label.set_color(fg)
        ax.tick_params(colors=fg)
        cbar_ax = fig.axes[-1]
        cbar_ax.tick_params(colors=fg)
        fig.tight_layout()

        # Replace the placeholder / previous plot
        self.placeholder.grid_forget()
        if self.canvas is not None:
            self.canvas.get_tk_widget().destroy()
        self.canvas = FigureCanvasTkAgg(fig, master=self.plot_box)
        self.canvas.draw()
        self.canvas.get_tk_widget().grid(row=0, column=0, sticky="nsew", padx=6, pady=6)

        self.acc_value.configure(text=f"{accuracy * 100:.1f} %")
        self.f1_value.configure(text=f"{f1:.3f}")
        self.status.configure(text=f"Evaluated on {len(y_test)} test samples.",
                              text_color="#66bb6a")


class RecognitionApp(ctk.CTk):
    def __init__(self):
        super().__init__()
        ctk.set_appearance_mode("dark")
        ctk.set_default_color_theme("blue")

        self.title("Beeldherkenning -  Prachtige componentenherkenner")
        self.geometry("1100x650")
        self.minsize(800, 500)

        # State
        self.model = None
        self.model_lock = threading.Lock()
        self.stream_thread = None
        self.stop_event = threading.Event()
        self.latest_frame = None          # RGB numpy array for display
        self.latest_prediction = "-"
        self.frame_lock = threading.Lock()
        self.fps = 0.0
        self.cm_window = None             # confusion matrix window (only one at a time)

        self._build_layout()
        self.protocol("WM_DELETE_WINDOW", self.on_close)
        # Start the GUI update loop
        self.after(GUI_REFRESH_MS, self.update_view)

    # ---------------------------------------------------------------- layout
    def _build_layout(self):
        self.grid_columnconfigure(1, weight=1)
        self.grid_rowconfigure(0, weight=1)

        # Sidebar
        side = ctk.CTkFrame(self, width=280, corner_radius=0)
        side.grid(row=0, column=0, sticky="nsew")
        side.grid_rowconfigure(20, weight=1)

        ctk.CTkLabel(side, text="Component\nRecognition",
                     font=ctk.CTkFont(size=22, weight="bold")).grid(
            row=0, column=0, padx=20, pady=(20, 15))

        # Training section
        ctk.CTkLabel(side, text="Training data (CSV)", anchor="w").grid(
            row=1, column=0, padx=20, sticky="ew")
        self.data_entry = ctk.CTkEntry(side, width=240)
        self.data_entry.insert(0, DEFAULT_DATA_PATH)
        self.data_entry.grid(row=2, column=0, padx=20, pady=(2, 8))

        self.browse_btn = ctk.CTkButton(side, text="Browse…", width=240,
                                        fg_color="transparent", border_width=1,
                                        command=self.browse_csv)
        self.browse_btn.grid(row=3, column=0, padx=20, pady=(0, 8))

        self.train_btn = ctk.CTkButton(side, text="Train model", width=240,
                                       command=self.start_training)
        self.train_btn.grid(row=4, column=0, padx=20, pady=(0, 6))

        self.train_progress = ctk.CTkProgressBar(side, width=240, mode="indeterminate")
        self.train_progress.grid(row=5, column=0, padx=20, pady=(0, 4))
        self.train_progress.set(0)

        self.model_status = ctk.CTkLabel(side, text="Model: not trained",
                                         text_color="orange", anchor="w")
        self.model_status.grid(row=6, column=0, padx=20, pady=(0, 6), sticky="ew")

        self.cm_btn = ctk.CTkButton(side, text="Confusion matrix", width=240,
                                    fg_color="transparent", border_width=1,
                                    command=self.open_confusion_matrix)
        self.cm_btn.grid(row=7, column=0, padx=20, pady=(0, 20))

        # Stream section
        ctk.CTkLabel(side, text="Stream URL", anchor="w").grid(
            row=8, column=0, padx=20, sticky="ew")
        self.url_entry = ctk.CTkEntry(side, width=240)
        self.url_entry.insert(0, DEFAULT_STREAM_URL)
        self.url_entry.grid(row=9, column=0, padx=20, pady=(2, 8))

        self.connect_btn = ctk.CTkButton(side, text="Connect to stream", width=240,
                                         fg_color="#2e7d32", hover_color="#1b5e20",
                                         command=self.toggle_stream)
        self.connect_btn.grid(row=10, column=0, padx=20, pady=(0, 6))

        self.stream_status = ctk.CTkLabel(side, text="Stream: disconnected",
                                          text_color="gray70", anchor="w")
        self.stream_status.grid(row=11, column=0, padx=20, pady=(0, 20), sticky="ew")

        # Prediction readout
        pred_box = ctk.CTkFrame(side)
        pred_box.grid(row=12, column=0, padx=20, pady=(0, 10), sticky="ew")
        ctk.CTkLabel(pred_box, text="Predicted component").pack(pady=(8, 0))
        self.pred_label = ctk.CTkLabel(pred_box, text="-",
                                       font=ctk.CTkFont(size=24, weight="bold"))
        self.pred_label.pack(pady=(0, 4))
        self.fps_label = ctk.CTkLabel(pred_box, text="", text_color="gray60")
        self.fps_label.pack(pady=(0, 8))

        # Appearance switch at the bottom
        self.mode_menu = ctk.CTkOptionMenu(side, values=["Dark", "Light", "System"],
                                           command=lambda m: ctk.set_appearance_mode(m.lower()),
                                           width=240)
        self.mode_menu.grid(row=21, column=0, padx=20, pady=20, sticky="s")

        # Main area: live view box + log
        main = ctk.CTkFrame(self, fg_color="transparent")
        main.grid(row=0, column=1, sticky="nsew", padx=15, pady=15)
        main.grid_columnconfigure(0, weight=1)
        main.grid_rowconfigure(1, weight=1)

        ctk.CTkLabel(main, text="Live view",
                     font=ctk.CTkFont(size=16, weight="bold"), anchor="w").grid(
            row=0, column=0, sticky="ew", pady=(0, 6))

        self.view_box = ctk.CTkFrame(main, corner_radius=12, border_width=2)
        self.view_box.grid(row=1, column=0, sticky="nsew")
        self.view_box.grid_columnconfigure(0, weight=1)
        self.view_box.grid_rowconfigure(0, weight=1)

        self.video_label = ctk.CTkLabel(self.view_box, text="No stream connected",
                                        text_color="gray60",
                                        font=ctk.CTkFont(size=16))
        self.video_label.grid(row=0, column=0, sticky="nsew", padx=6, pady=6)

        self.log_box = ctk.CTkTextbox(main, height=110, state="disabled")
        self.log_box.grid(row=2, column=0, sticky="ew", pady=(10, 0))

        self.log("Application started. Train the model and connect to the stream.")

    # --------------------------------------------------------------- helpers
    def log(self, msg):
        """Thread-safe log: always marshal to the GUI thread."""
        def _write():
            self.log_box.configure(state="normal")
            self.log_box.insert("end", f"{current_time()} - {msg}\n")
            self.log_box.see("end")
            self.log_box.configure(state="disabled")
        self.after(0, _write)

    def browse_csv(self):
        path = ctk.filedialog.askopenfilename(filetypes=[("CSV files", "*.csv"), ("All files", "*.*")])
        if path:
            self.data_entry.delete(0, "end")
            self.data_entry.insert(0, path)

    # -------------------------------------------------------------- training
    def start_training(self):
        self.train_btn.configure(state="disabled", text="Training…")
        self.train_progress.start()
        self.model_status.configure(text="Model: training…", text_color="gray70")
        threading.Thread(target=self._train_worker,
                         args=(self.data_entry.get().strip(),), daemon=True).start()

    # The actual training is done in a separate thread to avoid blocking the GUI. This function is called in that thread. Function from live_demo.py is used
    def _train_worker(self, data_path):
        self.log(f"Loading training data from {data_path}")
        try:
            # Load the training data from CSV and split into features and labels
            data = pd.read_csv(data_path)
            # Drop the photo_number and component_name columns from the features, not used in training
            x = data.drop(columns=["photo_number", "component_name"])
            # Use the component_name column as the labels for training
            y = data["component_name"]

            # Initialize RF clafficfier
            model = RandomForestClassifier(random_state=RANDOM_STATE,
                                           n_estimators=100, max_depth=None)
            # Log the time taken to train the model
            t0 = time.time()
            # Train the actual RF model on the x and y data
            model.fit(x, y)
            # Update the model in a thread-safe manner (prevent race conditions like in FreeRTOS)
            with self.model_lock:
                self.model = model

            # Count the number of classes in the model and log the time taken to train the model
            n_classes = len(model.classes_)
            self.log(f"Model trained on {len(data)} samples, {n_classes} classes "
                     f"in {time.time() - t0:.1f}s")
            self.after(0, lambda: self.model_status.configure(
                text=f"Model: trained ({n_classes} classes)", text_color="#66bb6a"))
        except Exception as e:
            self.log(f"Training failed: {e}")
            self.after(0, lambda: self.model_status.configure(
                text="Model: training failed", text_color="#ef5350"))
        finally:
            self.after(0, self._training_done)

    def _training_done(self):
        self.train_progress.stop()
        self.train_progress.set(0)
        self.train_btn.configure(state="normal", text="Retrain model" if self.model else "Train model")

    # Confusionmatrix
    # Runs in a background thread (started by ConfusionMatrixWindow). No plotting here:
    # Tk widgets may only be touched from the GUI thread, so the window draws the matrix.
    def create_confusion_matrix(self, data_path):
        data = pd.read_csv(data_path)
        x = data.drop(columns=['photo_number', 'component_name'])
        y = data['component_name']

        x_train, x_test, y_train, y_test = train_test_split(x, y, test_size=0.2, random_state=RANDOM_STATE)
        self.log(f"Test and train set generated (train_test_split). Training random forest.")
        random_forest = RandomForestClassifier(random_state=RANDOM_STATE, n_estimators=100, max_depth=None)
        train_starttime = datetime.now()
        random_forest.fit(x_train, y_train)
        self.log(f"Random forest trained in {(datetime.now() - train_starttime).total_seconds()} seconds.")
        self.log(f"Scoring random forest.")
        y_predicted = random_forest.predict(x_test)
        accuracy = accuracy_score(y_test, y_predicted)
        f1 = f1_score(y_test, y_predicted, average='weighted')     # y_true comes first
        self.log(f"Random forest accuracy: {round(accuracy * 100, 3)} %, with an f1 score of: {round(f1, 3)}.")

        return random_forest.classes_, y_test, y_predicted, accuracy, f1

    def open_confusion_matrix(self):
        # Reuse the window if it's already open, otherwise create a new one
        if self.cm_window is not None and self.cm_window.winfo_exists():
            self.cm_window.lift()
            self.cm_window.focus_force()
            return
        self.cm_window = ConfusionMatrixWindow(self)



    # ---------------------------------------------------------------- stream
    def toggle_stream(self):
        if self.stream_thread and self.stream_thread.is_alive():
            self.disconnect()
        else:
            self.connect()

    def connect(self):
        url = self.url_entry.get().strip()
        self.stop_event.clear()
        self.connect_btn.configure(state="disabled", text="Connecting…")
        self.stream_status.configure(text="Stream: connecting…", text_color="gray70")
        self.stream_thread = threading.Thread(target=self._stream_worker, args=(url,), daemon=True)
        self.stream_thread.start()

    def disconnect(self):
        self.stop_event.set()
        self.connect_btn.configure(state="disabled", text="Disconnecting…")

    def _set_disconnected_ui(self, status_text="Stream: disconnected", color="gray70"):
        self.connect_btn.configure(state="normal", text="Connect to stream",
                                   fg_color="#2e7d32", hover_color="#1b5e20")
        self.stream_status.configure(text=status_text, text_color=color)
        with self.frame_lock:
            self.latest_frame = None
        self.video_label.configure(image=None, text="No stream connected")
        try:
            self.video_label._label.configure(image="")   # CTkLabel keeps the old image otherwise
        except Exception:
            pass
        self.video_label.image = None
        self.fps_label.configure(text="")

    # Stream thread
    def _stream_worker(self, url):
        self.log(f"Connecting to {url}")
        cap = cv.VideoCapture(url)   # can block for a while
        if not cap.isOpened():
            self.log("Could not open video stream.")
            self.after(0, lambda: self._set_disconnected_ui("Stream: connection failed", "#ef5350"))
            return

        self.log("Stream connected.")
        self.after(0, lambda: (
            self.connect_btn.configure(state="normal", text="Disconnect",
                                       fg_color="#c62828", hover_color="#8e0000"),
            self.stream_status.configure(text="Stream: live", text_color="#66bb6a")))

        last = time.time()
        warned_no_model = False
        # Try to read frames until user stop or stream ends
        try:
            # Keep pulling frames from the stream as long as no stop is set
            while not self.stop_event.is_set():
                # Read frame
                ret, frame = cap.read()
                # foutje afvangen
                if not ret:
                    self.log("Can't receive frame (stream end?).")
                    break

                # Crop, important for calculate_parameters to work correctly
                h, w, _ = frame.shape
                frame = frame[0:h, CROP_LEFT:w - CROP_RIGHT]

                # Lock the model for prediction to avoid race conditions from other threads(like in FreeRTOS)s
                with self.model_lock:
                    model = self.model

                label = "-"
                # If there is a model...
                if model is not None:
                    try:
                        # Calculate the params using calculate_parameters
                        params = calculate_parameters(frame)
                        # Predict the label using the model and the calculated parameters, format to string
                        label = str(model.predict(params)[0])
                    except Exception as e:
                        label = "error"
                        self.log(f"Prediction error: {e}")
                    # Draw the bounding box on the frame using the label
                    frame = draw_bounding_box(frame, label)
                # Afvangen van geen model
                elif not warned_no_model:
                    self.log("Showing raw stream - train the model to get predictions.")
                    warned_no_model = True

                rgb = cv.cvtColor(frame, cv.COLOR_BGR2RGB)
                now = time.time()
                fps = 1.0 / max(now - last, 1e-6)
                last = now
                with self.frame_lock:
                    self.latest_frame = rgb
                    self.latest_prediction = label
                    self.fps = 0.9 * self.fps + 0.1 * fps
        finally:
            cap.release()
            self.log("Stream disconnected.")
            self.after(0, self._set_disconnected_ui)

    # Update the entire GUI view, including the video frame, prediction label, and FPS. This function is called periodically by the GUI main loop.
    def update_view(self):
        with self.frame_lock:
            frame = self.latest_frame
            pred = self.latest_prediction
            fps = self.fps

        if frame is not None:
            # Size to the surrounding box (not the label) so the view can't grow itself
            scaling = self.view_box._get_widget_scaling()
            box_w = max(self.view_box.winfo_width() / scaling - 20, 50)
            box_h = max(self.view_box.winfo_height() / scaling - 20, 50)
            fh, fw = frame.shape[:2]
            scale = min(box_w / fw, box_h / fh)
            size = (max(1, int(fw * scale)), max(1, int(fh * scale)))

            # Display the actyual frame in the GUI, convert to CTkImage for display
            img = ctk.CTkImage(light_image=Image.fromarray(frame), size=size)
            self.video_label.configure(image=img, text="")
            self.video_label.image = img          # keep a reference
            self.pred_label.configure(text=pred)
            self.fps_label.configure(text=f"{fps:.1f} FPS")

        # Call this function again after GUI_REFRESH_MS milliseconds to keep the GUI updated
        self.after(GUI_REFRESH_MS, self.update_view)

    def on_close(self):
        self.stop_event.set()
        if self.stream_thread and self.stream_thread.is_alive():
            self.stream_thread.join(timeout=2)
        self.destroy()


if __name__ == "__main__":
    app = RecognitionApp()
    app.mainloop()